with cleaned as (select id, customer_id, plan, start_date, end_date, monthly_fee, upper(plan) plan_upper from subscriptions where customer_id is not null and monthly_fee >= 90) select id, customer_id, lag(monthly_fee, 1) over (partition by customer_id order by monthly_fee, id) prev_monthly_fee, round(monthly_fee / sum(monthly_fee) over (partition by year(end_date), customer_id), 4) monthly_fee_share, ntile(5) over w_recent monthly_fee_bucket from cleaned where customer_id is null window w_recent as (partition by month(end_date) order by monthly_fee desc, id)
